  const keyList = await dapatkanDaftarApiKeyRotasi();
  logger2.info(`Memulai eksekusi Gemini AI (Model: ${targetModel}, Tersedia ${keyList.length} API Key)`);
  for (let i = 0; i < keyList.length; i++) {
    const activeKey = keyList[i];
    try {
      logger2.info(`[Rotasi AI #${i + 1}/${keyList.length}] Menggunakan ${activeKey.nama} (${activeKey.source})`);
      const genAI = new GoogleGenerativeAI(activeKey.rawKey);
      const geminiModel = genAI.getGenerativeModel({
        model: targetModel,
        ...options.systemInstruction && { systemInstruction: options.systemInstruction }
      });
      const result = await geminiModel.generateContent(options.prompt);
      const response = result.response;
      const teks = response.text();
      const usageMetadata = response.usageMetadata;
      if (activeKey.id && activeKey.source === "DB") {
        try {
          await db.update(apiKeys).set({
            totalRequest: activeKey.totalRequest ? activeKey.totalRequest + 1 : 1,
            terakhirDigunakan: /* @__PURE__ */ new Date()
          }).where(eq(apiKeys.id, activeKey.id));
        } catch {
        }
      }
      logger2.info(`\u2705 Eksekusi Gemini AI Berhasil dengan ${activeKey.nama}`);
      return {
        teks,
        tokenMasuk: usageMetadata?.promptTokenCount,
        tokenKeluar: usageMetadata?.candidatesTokenCount
      };
    } catch (error3) {
      logger2.warn(`\u274C Key #${i + 1} (${activeKey.nama}) gagal: ${error3?.message || error3}. Memutar ke key berikutnya...`);
      if (activeKey.id && activeKey.source === "DB") {
        try {
          await db.update(apiKeys).set({
            gagalHit: (activeKey.gagalHit || 0) + 1
          }).where(eq(apiKeys.id, activeKey.id));
        } catch {
        }
      }
    }
  }
  logger2.warn("Seluruh API Key Gemini tidak dapat digunakan. Mengaktifkan Engine Pengetahuan Terstruktur BrevetAI.");
