apiKeysRoutes.post(
  "/impor",
  zValidator(
    "json",
    external_exports.object({
      keys: external_exports.array(
        external_exports.object({
          nama: external_exports.string().min(1),
          apiKey: external_exports.string().min(1),
          prioritas: external_exports.number().optional()
        })
      )
    })
  ),
  async (c) => {
    try {
      const { keys } = c.req.valid("json");
      if (keys.length === 0) return gagal(c, "Data kunci kosong.", "BAD_REQUEST", 400);
      const created = [];
      for (const k of keys) {
        const [row] = await db.insert(apiKeys).values({
          nama: k.nama,
          apiKeyTerenkripsi: k.apiKey,
          prioritas: k.prioritas ?? 1,
          status: "AKTIF"
        }).returning();
        created.push({
          id: row.id,
          nama: row.nama,
          apiKey: row.apiKeyTerenkripsi,
          status: row.status
        });
      }
      return sukses(c, `Berhasil mengimpor ${created.length} API Keys!`, created, 201);
    } catch (error3) {
      if (isAppError(error3)) return gagal(c, error3.message, error3.code, error3.statusCode);
      return gagal(c, "Gagal mengimpor API keys.", "INTERNAL_ERROR", 500);
    }
  }
);
