async function pastikanTabelAda() {
  try {
    await db.execute(sql2`
      CREATE TABLE IF NOT EXISTS studi_kasus (
        id TEXT PRIMARY KEY DEFAULT gen_random_uuid(),
        judul TEXT NOT NULL,
        slug TEXT NOT NULL UNIQUE,
        deskripsi TEXT,
        level TEXT DEFAULT 'MENENGAH',
        tag TEXT DEFAULT 'PPh OP',
        durasi_menit INTEGER DEFAULT 45,
        skenario_teks TEXT,
        soal_json JSONB,
        terbit BOOLEAN DEFAULT true,
        created_at TIMESTAMP DEFAULT NOW(),
        updated_at TIMESTAMP DEFAULT NOW()
      );
    `);
  } catch (err) {
    console.error("Gagal auto-create tabel studi_kasus:", err);
  }
}
async function ambilSemuaStudiKasus() {
  try {
    await pastikanTabelAda();
    let list = await db.select().from(studiKasus).orderBy(desc(studiKasus.createdAt));
    if (!Array.isArray(list) || list.length === 0) {
      for (const item of DUMMY_CASES) {
        try {
          await db.insert(studiKasus).values({
            judul: item.judul,
            slug: item.slug,
            deskripsi: item.deskripsi,
            level: item.level,
            tag: item.tag,
            durasiMenit: item.durasiMenit,
            skenarioTeks: item.skenarioTeks,
            terbit: item.terbit
          }).onConflictDoNothing();
        } catch {
        }
      }
      list = await db.select().from(studiKasus).orderBy(desc(studiKasus.createdAt));
    }
    return Array.isArray(list) && list.length > 0 ? list : DUMMY_CASES;
  } catch (err) {
    console.error("Gagal mengambil daftar studi kasus, menggunakan fallback:", err);
    return DUMMY_CASES;
  }
}
async function ambilStudiKasusBySlug(slug) {
  try {
    await pastikanTabelAda();
    const res = await db.select().from(studiKasus).where(eq(studiKasus.slug, slug)).limit(1);
    if (res[0]) return res[0];
  } catch {
  }
  return DUMMY_CASES.find((c) => c.slug === slug || c.id === slug) || DUMMY_CASES[0];
}
async function ambilStudiKasusById(id) {
  try {
    await pastikanTabelAda();
    const res = await db.select().from(studiKasus).where(eq(studiKasus.id, id)).limit(1);
    if (res[0]) return res[0];
  } catch {
  }
  return DUMMY_CASES.find((c) => c.id === id || c.slug === id) || DUMMY_CASES[0];
}
async function tambahStudiKasus(data) {
  await pastikanTabelAda();
  const generatedSlug = data.slug?.trim() || data.judul.toLowerCase().replace(/\s+/g, "-").replace(/[^a-z0-9-]/g, "");
  const [baru] = await db.insert(studiKasus).values({
    judul: data.judul,
    slug: generatedSlug,
    deskripsi: data.deskripsi || "",
    level: data.level || "MENENGAH",
    tag: data.tag || "PPh OP",
    durasiMenit: Number(data.durasiMenit) || 45,
    skenarioTeks: data.skenarioTeks || "",
    terbit: data.terbit !== void 0 ? data.terbit : true
  }).returning();
  return baru;
}
async function updateStudiKasus(id, data) {
  await pastikanTabelAda();
  const updateData = { updatedAt: /* @__PURE__ */ new Date() };
  if (data.judul !== void 0) updateData.judul = data.judul;
  if (data.slug !== void 0) updateData.slug = data.slug;
  if (data.deskripsi !== void 0) updateData.deskripsi = data.deskripsi;
  if (data.level !== void 0) updateData.level = data.level;
  if (data.tag !== void 0) updateData.tag = data.tag;
  if (data.durasiMenit !== void 0) updateData.durasiMenit = Number(data.durasiMenit);
  if (data.skenarioTeks !== void 0) updateData.skenarioTeks = data.skenarioTeks;
  if (data.terbit !== void 0) updateData.terbit = data.terbit;
  const [hasil] = await db.update(studiKasus).set(updateData).where(eq(studiKasus.id, id)).returning();
  return hasil;
}
async function hapusStudiKasus(id) {
  await pastikanTabelAda();
  await db.delete(studiKasus).where(eq(studiKasus.id, id));
  return true;
}

// src/features/studi-kasus/studi-kasus.routes.ts
var studiKasusRoutes = new Hono2();
studiKasusRoutes.get("/", async (c) => {
  try {
    const list = await ambilSemuaStudiKasus();
    return sukses(c, list, "Berhasil mengambil daftar studi kasus");
  } catch (err) {
    return gagal(c, err.message || "Gagal mengambil studi kasus", "INTERNAL_ERROR", 500);
  }
});
studiKasusRoutes.get("/:slug", async (c) => {
  try {
    const slugOrId = c.req.param("slug");
    let detail = await ambilStudiKasusBySlug(slugOrId);
    if (!detail) {
      detail = await ambilStudiKasusById(slugOrId);
    }
    if (!detail) {
      return gagal(c, "Studi kasus tidak ditemukan", "NOT_FOUND", 404);
    }
    return sukses(c, detail, "Berhasil mengambil detail studi kasus");
  } catch (err) {
    return gagal(c, err.message || "Gagal mengambil detail studi kasus", "INTERNAL_ERROR", 500);
  }
});
studiKasusRoutes.post("/admin", async (c) => {
  try {
    const body = await c.req.json();
    if (!body.judul) {
      return gagal(c, "Judul studi kasus wajib diisi", "BAD_REQUEST", 400);
    }
    const baru = await tambahStudiKasus(body);
    return sukses(c, baru, "Berhasil membuat studi kasus baru", 201);
  } catch (err) {
    return gagal(c, err.message || "Gagal menambah studi kasus", "INTERNAL_ERROR", 500);
  }
});
studiKasusRoutes.patch("/admin/:id", async (c) => {
  try {
    const id = c.req.param("id");
    const body = await c.req.json();
    const updated = await updateStudiKasus(id, body);
    if (!updated) {
      return gagal(c, "Studi kasus tidak ditemukan", "NOT_FOUND", 404);
    }
    return sukses(c, updated, "Berhasil memperbarui studi kasus");
  } catch (err) {
    return gagal(c, err.message || "Gagal memperbarui studi kasus", "INTERNAL_ERROR", 500);
  }
});
studiKasusRoutes.delete("/admin/:id", async (c) => {
  try {
    const id = c.req.param("id");
    await hapusStudiKasus(id);
    return sukses(c, { id }, "Berhasil menghapus studi kasus");
  } catch (err) {
    return gagal(c, err.message || "Gagal menghapus studi kasus", "INTERNAL_ERROR", 500);
  }
});

